protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    // Map each source vertex to its outgoing edge in the tour
    java.util.Map<V,E> sourceToEdge = new java.util.HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        sourceToEdge.put(src, e);
    }
    // Pick an arbitrary starting vertex
    V start = graph.getEdgeSource(tour.iterator().next());
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    double totalWeight = 0.0;
    V current = start;
    // Traverse the tour until we return to the start
    do{
        E e = sourceToEdge.get(current);
        if (e == null){
            // The set does not form a valid tour
            return null;
        }
        edgeList.add(e);
        totalWeight += graph.getEdgeWeight(e);
        current = graph.getEdgeTarget(e);
    }while (!current.equals(start));
    // The tour starts and ends at the same vertex
    return new org.jgrapht.traverse.GraphPathImpl<>(graph, start, start, edgeList, totalWeight);
}

