public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Split the base path into components, keeping leading empty string for absolute paths
    String[] baseParts = path.split("/", -1);
    List<String> stack = new ArrayList<>();
    for (String part : baseParts) {
        stack.add(part);
    }
    // Process each component of the relative path
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // no-op
        } else if (part.equals("..")) {
            // Pop the last component if possible
            if (stack.size() > 1) {
                stack.remove(stack.size() - 1);
            } else if (stack.size() == 1 && !stack.get(0).isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    // Reconstruct the path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }
    // Handle the special case where the result is an empty string (e.g., root)
    return result.length() == 0 ? "/" : result.toString();
}

