protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long chunkEnd = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, chunkEnd));
        current = chunkEnd;
    }
    return ranges;
}

