        else if (candidate % 2 == 0) prime = candidate == 2;
        else {
            for (int i = 3; i * i <= candidate; i += 2) {
                if (candidate % i == 0) { prime = false; break; }
            }
        }
        if (prime) return candidate;
        candidate += 2;
    }
}

